-- Add Test marking defaults per exam. Code has the same built-in fallback and tolerates a
-- missing column or malformed JSON, so this can be applied after that code is live.
-- Existing student/test rows are not read or changed by this migration.
alter table public.exam_catalog add column if not exists marking_scheme jsonb;
alter table public.exam_catalog drop constraint if exists exam_catalog_marking_scheme_object;
alter table public.exam_catalog add constraint exam_catalog_marking_scheme_object check (marking_scheme is null or jsonb_typeof(marking_scheme) = 'object');

update public.exam_catalog set marking_scheme = $json${"full":{"total":300,"perSubject":{"Physics":100,"Chemistry":100,"Maths":100},"papers":[{"id":"advanced-paper-1","label":"Paper 1","total":180,"perSubject":{"Physics":60,"Chemistry":60,"Maths":60}},{"id":"advanced-paper-2","label":"Paper 2","total":180,"perSubject":{"Physics":60,"Chemistry":60,"Maths":60}}]},"other":{"total":180,"perSubject":{"Physics":60,"Chemistry":60,"Maths":60}},"combine":"sum_papers","source":"NTA JEE (Main) and IIT JEE (Advanced) 2026","notes":"Full Mock asks Main, Advanced Paper 1 only, or Advanced Paper 1 + Paper 2. Both Advanced papers combine to 360."}$json$::jsonb where id = 'jee';
update public.exam_catalog set marking_scheme = $json${"full":{"total":200,"perSubject":{"Physics":50,"Chemistry":50,"Maths":100,"Biology":100}},"other":{"total":100,"perSubject":{"Physics":25,"Chemistry":25,"Maths":50,"Biology":50}},"combine":"sum_subjects","source":"Maharashtra State CET Cell, MHT CET 2026","notes":"PCM and PCB are alternative groups; do not enter Maths and Biology for one official full paper."}$json$::jsonb where id = 'mht-cet';
