update public.exam_catalog set marking_scheme = $json${"full":{"total":500,"perSubject":{"Maths":160,"Biology":160,"Physics":140,"Chemistry":140,"Aptitude":40,"English":20}},"other":{"total":250,"perSubject":{"Maths":80,"Biology":80,"Physics":70,"Chemistry":70,"Aptitude":20,"English":10}},"combine":"sum_subjects","source":"VIT, VITEEE 2026","notes":"Maths and Biology are alternative streams."}$json$::jsonb where id = 'viteee';
